<template>
  <component
    :is="to ? NuxtLink : 'div'"
    :to="to"
    :class="cn('flex items-start gap-3', to && 'no-underline text-inherit')"
  >
    <template v-if="icon">
      <component :is="icon" class="w-6 h-6 stroke-muted-foreground shrink-0 mt-[2px]" />
    </template>
    <div :class="cn('flex flex-col', contentClass)">
      <p class="text-sm text-accent-foreground">
        {{ label }}
      </p>
      <slot>
        <Skeleton v-if="loading" class="w-48 h-6 rounded-full" />
        <p v-else-if="error" class="text-destructive text-md">Failed to get data</p>
        <p v-else class="font-medium line-clamp-5">
          {{ value || '-' }}
        </p>
      </slot>
    </div>
  </component>
</template>
<script lang="ts" setup>
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import { cn } from '@/lib/utils';

const NuxtLink = resolveComponent('NuxtLink');

withDefaults(
  defineProps<{
    label: string;
    value?: string | null;
    icon?: any;
    loading?: boolean;
    error?: string;
    contentClass?: string;
    to?: TypedNuxtLink['to'];
  }>(),
  {
    value: '-',
    icon: undefined,
    error: undefined,
    contentClass: undefined,
    to: undefined,
  }
